"  useEffect(() => {
    localStorage.setItem('pos_terminal_settings', JSON.stringify(posSettings));
  }, [posSettings]);

  const [isMaximized, setIsMaximized] = useState(true);

  useEffect(() => {
    if (window.require) {
      try {
        const { ipcRenderer } = window.require('electron');
        const handleState = (event, state) => {
          setIsMaximized(state.isMaximized);
        };
        ipcRenderer.on('window-state-changed', handleState);
        return () => {
          ipcRenderer.removeListener('window-state-changed', handleState);
        };
      } catch (e) {
        console.warn("Electron IPC listener failed:", e);
      }
    }
  }, []);"
